let state;try{state=JSON.parse(localStorage.getItem('butterfly-desk-v1'))||seed()}catch{state=seed()}
let page='Overview',pipelineView='Board',sourceFilter='All sources',selectedLead=1,search='',cleanupScene=null,toastTimer;
const save=()=>{try{localStorage.setItem('butterfly-desk-v1',JSON.stringify(state))}catch{toast('Browser storage is unavailable. Keep this tab open to retain changes.')}};
const lead=id=>state.leads.find(l=>l.id===Number(id));
const booked=()=>state.leads.filter(l=>l.stage===3).sort((a,b)=>a.date.localeCompare(b.date));
const receipts=id=>state.payments.filter(p=>p.type==='Traveller receipt'&&(!id||p.leadId===id)).reduce((s,p)=>s+p.amount,0);
const avatar=(n)=>`<span class="avatar">${esc(initials(n))}</span>`;
const status=l=>`<span class="tag ${stageClass[l.stage]}">${stages[l.stage]}</span>`;
const button=(label,action,icon='ArrowRight',style='light')=>`<button class="btn ${style}" data-action="${action}">${i(icon)}${label}</button>`;
const butterfly=`<svg class="butterfly" viewBox="0 0 44 44" fill="none"><path d="M21 22C-1 0 1 37 21 25C7 44 29 46 23 26C44 38 44 0 23 22" fill="#456449"/><path d="M21 22C5 6 5 29 21 24" fill="#a7bd85"/><path d="M23 22C37 7 40 29 23 24" fill="#d2ba81"/><path d="M22 18V32" stroke="#244635" stroke-width="1.5"/><path d="M22 19L18 14M22 19L26 14" stroke="#244635"/></svg>`;
const navigation=[['Overview','LayoutDashboard'],['Enquiries','Users'],['Itinerary studio','Map'],['Template library','FileText'],['Bookings','CalendarDays'],['Payments','Wallet'],['Suppliers','Building2'],['Automations','Workflow'],['Insights','ChartNoAxesCombined']];
function shell(){return `<div class="shell"><aside class="sidebar"><div class="brand">${butterfly}<div><strong>butterfly desk<span style="color:#94a87c">.</span></strong><small>The Rainbow Butterflies</small></div></div><div class="workspace"><span class="square">${i('Mountain')}</span><div><strong>The Rainbow Butterflies</strong><small>Team workspace</small></div>${i('ChevronDown')}</div><div class="nav-label">YOUR WORKSPACE</div><nav class="nav">${navigation.map(([n,icon],j)=>`<button data-page="${n}" aria-label="${n}" class="${page===n?'active':''} ${n==='Automations'?'nav-break':''}" ${page===n?'aria-current="page"':''}>${i(icon)}<span>${n}</span>${n==='Enquiries'?`<b class="badge">${state.leads.filter(l=>l.stage<3).length}</b>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="nature-note">${i('Leaf')}<strong>Small footprints. Big stories.</strong>More time for people.<br>Less time on paperwork.</div><div class="profile">${avatar('Bonjeet Khamon')}<div><strong>Bonjeet Khamon</strong><small>Founder · Workspace admin</small></div><button class="icon-btn" data-page="Settings" aria-label="Workspace settings">${i('Settings')}</button></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb"><span>Workspace</span>${i('ChevronRight')}<strong>${page}</strong></div><div class="top-actions"><label class="search">${i('Search')}<input id="global-search" aria-label="Search travellers" placeholder="Search your workspace" value="${esc(search)}"><kbd>⌘ K</kbd></label><span class="demo-pill"><span class="dot"></span>DEMO WORKSPACE</span><button class="icon-btn notification" data-action="notifications" aria-label="View reminders">${i('Bell')}</button>${avatar('Bonjeet Khamon')}</div></header><div class="content">${searchResults()}${pages[page]()}<div class="footer-note"><span>${i('Leaf')}Made for journeys that mean something.</span><span>Sample data · 5 October 2026 · Saved on this device</span></div></div></main></div>`;}
function heading(title,desc,actions='',eyebrow='YOUR TRIP OPERATIONS, CONNECTED'){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div><div class="heading-actions">${actions}</div></div>`}
function metric(label,value,foot,icon){return `<div class="metric"><div class="metric-label">${label}${i(icon)}</div><div class="metric-value">${value}</div><div class="metric-foot">${foot}</div></div>`}
function searchResults(){if(!search)return '';let found=state.leads.filter(l=>`${l.name} ${l.destination} ${l.trip}`.toLowerCase().includes(search.toLowerCase()));return `<div class="search-results"><strong>Travellers & journeys matching “${esc(search)}”</strong>${found.length?found.map(l=>`<button class="search-result" data-lead="${l.id}">${esc(l.name)}<small>${esc(l.trip)}</small></button>`).join(''):'<p class="notice">No matching traveller or journey.</p>'}</div>`}
function overview(){const active=state.leads.filter(l=>l.stage<3),pending=state.tasks.filter(t=>!t.done);return heading('A little less admin.<br class="mobile-brand"> A lot more adventure.',"Good morning, Bonjeet. Here’s where your journeys stand.",`<span class="calendar-chip">${i('CalendarDays')}Mon, 05 Oct</span>${button('Review incoming enquiries','review-inbox','Users','primary')}`,'MONDAY, MEET POSSIBILITY')+`<div class="metrics">${metric('Active enquiries',String(active.length).padStart(2,'0'),`<span>${active.filter(l=>l.stage===0).length} new</span> waiting for a conversation`,'Users')}${metric('Proposal pipeline',money(state.leads.filter(l=>l.stage===2).reduce((s,l)=>s+l.value,0)),`<span>${state.leads.filter(l=>l.stage===2).length} proposal</span> ready for a follow-up`,'FileText')}${metric('Upcoming departures',String(booked().length).padStart(2,'0'),'<span>Next up</span> Meghalaya · 12 Oct','Compass')}${metric('Payments collected',money(receipts()),'<span>Recorded receipts</span> in this demo','Wallet')}</div><div class="feature-grid"><section class="hero"><div class="hero-copy"><div class="eyebrow">ROOTED IN THE NORTHEAST</div><h2>Extraordinary journeys.<br><em>Effortlessly<br>orchestrated.</em></h2><p>From the first hello to the last winding road. Every detail, in one place.</p>${button('Prepare a proposal','studio','FileText','primary')}</div><div id="landscape" class="scene" role="img" aria-label="Interactive three-dimensional floating island with mountains, a river, trees and a homestay. Drag to rotate."></div><div class="scene-label"><span class="dot"></span>8 states. Endless possibilities.</div><div class="hero-coordinate">${i('Compass')}25.4670° N &nbsp; 91.3662° E &nbsp; · &nbsp; DRAG TO EXPLORE</div></section><section class="panel"><div class="panel-header"><h3>On the horizon</h3><button class="btn ghost" data-page="Bookings">View all ${i('ArrowUpRight')}</button></div><div class="departures">${booked().slice(0,3).map((l,j)=>`<div class="departure" role="button" tabindex="0" data-booking="${l.id}"><span class="trip-thumb ${j===1?'tea':j===2?'festival':''}"></span><div><strong>${esc(l.trip)}</strong><p>${formatDate(l.date)} · ${l.guests} travellers</p><small>${(state.checks[l.id]||[]).filter(Boolean).length}/6 departure checks complete</small></div><span class="arrow">${i('ChevronRight')}</span></div>`).join('')}</div><div class="departure-bottom">${i('Leaf')}Good journeys begin with small details.</div></section></div><div class="lower-grid"><section class="panel"><div class="panel-header"><div><h3>Every enquiry is a possibility</h3><p class="sub">A clear path from curious to confirmed.</p></div><button class="btn ghost" data-page="Enquiries">Open pipeline ${i('ArrowUpRight')}</button></div><div class="mini-pipeline">${stages.map((s,j)=>`<div class="stage-stat"><label>${s}</label><strong>${String(state.leads.filter(l=>l.stage===j).length).padStart(2,'0')}</strong><small>${money(state.leads.filter(l=>l.stage===j).reduce((a,l)=>a+l.value,0))}</small></div>`).join('')}</div>${leadTable(state.leads.filter(l=>l.stage<3).slice(0,3),true)}</section><section class="panel"><div class="panel-header"><h3>Your next little steps</h3><span class="tag gray">${pending.length} to do</span></div>${state.tasks.slice(0,3).map(taskRow).join('')}<div style="padding:8px 21px 13px"><button class="btn ghost" data-action="notifications">See all reminders ${i('ArrowRight')}</button></div></section></div>`}
function taskRow(t){return `<div class="task-row ${t.done?'completed':''}"><button class="check ${t.done?'done':''}" data-task="${t.id}" aria-label="${t.done?'Reopen':'Complete'} ${esc(t.title)}" aria-pressed="${t.done}">${t.done?i('Check'):''}</button><div><strong>${esc(t.title)}</strong><small>${esc(t.sub)}</small><span class="tag ${t.due<=today?'coral':'gray'}">${t.due===today?'Today':formatDate(t.due)}</span></div></div>`}
function leadTable(items,compact=false){return `<div class="table-wrap"><table><thead><tr><th>Traveller</th><th>Journey</th><th>Status</th>${compact?'':'<th>Owner</th><th>Value</th><th>Next action</th>'}</tr></thead><tbody>${items.map(l=>`<tr class="clickable" data-lead="${l.id}" tabindex="0"><td><div class="person-cell">${avatar(l.name)}<div><strong>${esc(l.name)}</strong><small>${esc(l.source)}</small></div></div></td><td>${esc(l.destination)}<div style="font-size:8px;color:#96a08d;margin-top:4px">${l.days} days · ${l.guests} travellers</div></td><td>${status(l)}</td>${compact?'':`<td>${esc(l.owner)}</td><td>${money(l.value)}</td><td>${formatDate(l.due)}</td>`}</tr>`).join('')}</tbody></table>${items.length?'':'<div class="empty">No enquiries match this source.</div>'}</div>`}
function enquiries(){let items=state.leads.filter(l=>sourceFilter==='All sources'||l.source===sourceFilter);return heading('Incoming enquiries','Review incoming leads, assign a teammate and set the next action.',button('Log enquiry manually','new-enquiry','Plus','light'),'TEAM ENQUIRY INBOX')+inboxStrip()+`<div class="toolbar"><div class="tabs">${['Board','List'].map(v=>`<button data-view="${v}" class="${pipelineView===v?'active':''}">${v==='Board'? 'Pipeline board':'Traveller list'}</button>`).join('')}</div><select class="filter-select" id="source-filter" aria-label="Filter by source">${['All sources','Website','Instagram','Referral','LinkedIn','WhatsApp'].map(s=>`<option ${s===sourceFilter?'selected':''}>${s}</option>`).join('')}</select></div>${pipelineView==='List'?`<section class="panel">${leadTable(items)}</section>`:`<div class="kanban">${stages.map((s,j)=>`<section class="kanban-column"><div class="column-title"><span class="dot"></span>${s}<span class="count">${items.filter(l=>l.stage===j).length}</span></div>${items.filter(l=>l.stage===j).map(l=>`<article class="lead-card" data-lead="${l.id}" role="button" tabindex="0"><div class="card-top"><span class="tag ${stageClass[j]}">${esc(l.source)}</span>${i('ArrowUpRight')}</div><h4>${esc(l.name)}</h4><p>${esc(l.destination)} · ${esc(l.segment)}</p><div class="lead-meta"><span>${i('Users')}${l.guests} guests</span><span>${i('CalendarDays')}${formatDate(l.date)}</span></div><div class="card-bottom"><strong>${money(l.value)}</strong>${avatar(l.owner)}</div><div class="card-due">${i('Clock')}${j===3?'Trip preparation':'Next action'} · ${formatDate(l.due)}</div></article>`).join('')||'<div class="empty">A little room for possibility.</div>'}</section>`).join('')}</div>`}`}
function initialRoute(l){
 if(l.destination==='Meghalaya')return JSON.parse(JSON.stringify(routes.slice(0,Math.min(l.days,7))));
 const places=l.destination==='Assam'?['Guwahati','Kaziranga','Jorhat','Majuli','Guwahati']:l.destination==='Nagaland'?['Dimapur','Kohima','Kisama','Khonoma','Kohima','Dimapur']:[l.destination];
 return Array.from({length:l.days},(_,j)=>({title:j===0?'A warm Northeast welcome':j===l.days-1?'Until next time, Northeast':l.destination==='Assam'?'Tea, traditions & local stories':'A day of culture and connection',place:places[Math.min(j,places.length-1)],detail:j===0?'Meet your local host and settle into your stay. Transfer timing and accommodation are subject to confirmation.':j===l.days-1?'A relaxed breakfast and your onward transfer, with time planned around your departure.':'A locally guided day shaped around the traveller brief. Confirm the route, permissions, access needs and availability with the operator.',type:j===0?'Arrival · Private transfer':j===l.days-1?'Departure · Private transfer':'Culture · Local guide'}));
}
function getProposal(){if(!state.proposals[selectedLead])state.proposals[selectedLead]={days:initialRoute(lead(selectedLead)),costs:{stays:42000,transport:33600,experiences:18000,meals:12000},margin:25,versions:[]};return state.proposals[selectedLead]}
function calc(p){let cost=Object.values(p.costs).reduce((s,n)=>s+Number(n),0);return {cost,total:Math.round(cost*(1+Number(p.margin)/100))}}
function studio(){const l=lead(selectedLead)||state.leads[0];selectedLead=l.id;const p=getProposal(),c=calc(p);return `<div class="print-only"><h1>The Rainbow Butterflies</h1><p>Travel proposal for ${esc(l.name)} · ${formatDate(l.date)} · ${l.guests} travellers</p><p>Illustrative demo proposal. Route, availability and prices require operator approval.</p></div>`+heading('Make room for the remarkable.','Build a considered itinerary. Put a confident number behind it.',`${button('Preview','preview-proposal','ExternalLink')}${button('Save proposal','save-proposal','Check','primary')}`,'ITINERARY STUDIO')+`<div class="toolbar"><select id="studio-traveller" class="filter-select" aria-label="Select traveller">${state.leads.map(x=>`<option value="${x.id}" ${x.id===l.id?'selected':''}>${esc(x.name)} · ${esc(x.destination)}</option>`).join('')}</select><span class="saved-note">${p.versions.length?'Version '+p.versions.length+' saved':'Working draft'} · Human approval before sharing</span></div><div class="split-view"><div class="stack"><section class="panel padded"><div class="eyebrow">THE TRAVELLER BRIEF</div><h3 style="font-size:19px;margin:8px 0">${esc(l.trip)}</h3><div class="lead-meta"><span>${i('CalendarDays')}${formatDate(l.date)} · ${p.days.length} days</span><span>${i('Users')}${l.guests} travellers</span><span>${i('Wallet')}Budget ${money(l.budget)}</span></div><p class="section-intro" style="font-size:11px">${esc(l.preferences)}</p><div class="info-banner">${i('ShieldCheck')}Draft itinerary components are illustrative. Confirm route feasibility, accessibility, rates and availability with local partners.</div></section><section class="panel"><div class="panel-header"><h3>A day-by-day story</h3><span class="tag">${p.days.length} days</span></div>${p.days.map((d,j)=>`<div class="day"><span class="day-num">${String(j+1).padStart(2,'0')}</span><div class="day-body"><div class="eyebrow" style="font-size:8px;letter-spacing:1px;margin-bottom:5px">${esc(d.place)}</div><h4>${esc(d.title)}</h4><p>${esc(d.detail)}</p><span class="tag gray">${esc(d.type)}</span></div><div class="day-actions"><button class="icon-btn" data-day-up="${j}" aria-label="Move day ${j+1} up" ${j===0?'disabled':''}>${i('ArrowUp')}</button><button class="icon-btn" data-day-down="${j}" aria-label="Move day ${j+1} down" ${j===p.days.length-1?'disabled':''}>${i('ArrowDown')}</button><button class="icon-btn" data-day-remove="${j}" aria-label="Remove day ${j+1}">${i('Trash2')}</button></div></div>`).join('')}${p.days.length?'':'<div class="empty">Add a day from the component library to begin.</div>'}<div style="padding:17px 22px">${button('Write a custom day','custom-day','Plus')}</div></section></div><div class="stack"><section class="panel padded"><div class="eyebrow">COSTING & QUOTE</div><h3 style="font-size:14px">A clear price. A happy journey.</h3><div style="margin-top:16px">${Object.entries(p.costs).map(([k,v])=>`<label class="money-line">${{stays:'Stays',transport:'Transport',experiences:'Guides & experiences',meals:'Meals'}[k]}<input class="cost-input" data-cost="${k}" type="number" min="0" max="10000000" value="${v}" aria-label="${k} cost"></label>`).join('')}<div class="money-line total"><span>Total operating cost</span><span id="cost-total">${money(c.cost)}</span></div><label class="money-line">Markup on cost (%)<input id="markup" type="number" min="0" max="200" class="cost-input" value="${p.margin}" aria-label="Markup percentage"></label><div class="money-line total"><span>Proposed group price</span></div><div class="quote-total" id="quote-total">${money(c.total)}</div><p class="notice" id="per-person">${money(c.total/l.guests)} per traveller · ${l.guests} travellers</p><p class="notice" style="margin-top:8px">Illustrative pricing. Taxes, inclusions and cancellation terms must be finalised before issuing a real quote.</p></div></section><section class="panel padded template-library"><div class="eyebrow">COMPONENT LIBRARY</div><h3 style="font-size:13px">Add a little local magic</h3><button class="btn ghost" data-page="Template library">Browse approved library ${i('ArrowRight')}</button>${[{title:'A Khasi kitchen afternoon',place:'Shillong',type:'Food · Community experience',detail:'Cook a seasonal meal with a local host and hear the stories behind the ingredients.'},{title:'Tea gardens, unhurried',place:'Jorhat, Assam',type:'Tea · Estate visit',detail:'Walk through tea gardens with a local guide and enjoy a tasting, subject to estate permission.'},{title:'A gentle day in the hills',place:'Shillong',type:'Accessible pace · Rest day',detail:'A slower day with short walks, scenic stops and plenty of time to rest. Confirm individual access needs.'}].map((d,j)=>`<div class="template-item"><div><strong>${d.title}</strong><small>${d.place}</small></div><button class="icon-btn" data-template="${j}" aria-label="Add ${d.title}">${i('Plus')}</button></div>`).join('')}</section><section class="panel padded"><h3 style="font-size:13px">Version history</h3>${p.versions.length?p.versions.slice().reverse().map(v=>`<div class="version"><span>v${v.n} · ${v.date}</span><strong>${money(v.total)}</strong></div>`).join(''):'<p class="notice" style="margin-top:10px">Save your first proposal to capture its itinerary and price.</p>'}</section></div></div>`}
function bookings(){return heading('The next chapter is almost here.','Confirmed journeys, with every little detail accounted for.','','DEPARTURE DESK')+`<div class="cards-grid">${booked().map((l,j)=>{let done=(state.checks[l.id]||[]).filter(Boolean).length;return `<article class="panel"><div class="destination-art ${l.destination==='Assam'?'tea':l.destination==='Nagaland'?'festival':''}"><span class="art-tag">${esc(l.destination)} · ${formatDate(l.date)}</span></div><div class="card-body"><span class="tag green">Confirmed journey</span><h3>${esc(l.trip)}</h3><p>${esc(l.name)} · ${l.guests} travellers · ${l.days} days</p><div class="row"><span class="notice">Departure readiness</span><strong style="font-size:10px">${done}/6 complete</strong></div><div class="progress"><span style="width:${done/6*100}%"></span></div><div class="row"><span class="notice">Balance ${money(Math.max(0,l.value-receipts(l.id)))}</span><button class="btn ghost" data-booking="${l.id}">Open trip ${i('ArrowRight')}</button></div></div></article>`}).join('')}</div>`}
function payments(){let value=booked().reduce((s,l)=>s+l.value,0),paid=receipts();return heading('Keep the numbers as clear as the river.','Track traveller receipts, balances and partner payments.',button('Record payment','record-payment','Plus','primary'),'PAYMENT LEDGER')+paymentOperations()+`<div class="metrics">${metric('Confirmed booking value',money(value),'Across confirmed demo bookings','FileText')}${metric('Traveller receipts',money(paid),'Recorded manually in this workspace','Wallet')}${metric('Outstanding balance',money(value-paid),'Pending traveller payments','Clock')}${metric('Supplier payments',money(state.payments.filter(p=>p.type==='Supplier payment').reduce((s,p)=>s+p.amount,0)),'Partner outgoings recorded','Building2')}</div><div class="stack"><section class="panel"><div class="panel-header"><h3>Balances to keep an eye on</h3><span class="tag">${booked().length} bookings</span></div><div class="table-wrap"><table><thead><tr><th>Journey</th><th>Booking value</th><th>Received</th><th>Balance</th><th>Balance due</th><th></th></tr></thead><tbody>${booked().map(l=>`<tr><td><strong>${esc(l.name)}</strong><div class="notice">${esc(l.trip)}</div></td><td>${money(l.value)}</td><td>${money(receipts(l.id))}</td><td>${money(Math.max(0,l.value-receipts(l.id)))}</td><td>${formatDate(l.due)}</td><td><button class="btn ghost" data-pay="${l.id}">Record ${i('Plus')}</button></td></tr>`).join('')}</tbody></table></div></section><section class="panel"><div class="panel-header"><h3>Recent ledger entries</h3>${button('Export CSV','export-payments','Download')}</div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Traveller / booking</th><th>Type</th><th>Date</th><th>Amount</th></tr></thead><tbody>${state.payments.slice().reverse().map(p=>`<tr><td>${esc(p.ref)}</td><td>${esc(lead(p.leadId)?.name||'Booking')}</td><td><span class="tag ${p.type==='Supplier payment'?'coral':'green'}">${p.type}</span></td><td>${formatDate(p.date)}</td><td>${money(p.amount)}</td></tr>`).join('')}</tbody></table></div></section></div>`}
function suppliers(){return heading('Local people. Lasting partnerships.','One home for your hosts, guides, rates and confirmations.',button('Add partner','new-supplier','Plus','primary'),'PARTNER DIRECTORY')+`<div class="info-banner">${i('Heart')}These are fictional demo partners and indicative rates. The real workspace would hold your verified local relationships.</div><div class="cards-grid">${state.suppliers.map(s=>`<article class="panel card-body"><div style="display:flex;justify-content:space-between;align-items:flex-start"><span class="supplier-icon">${i(s.type==='Stay'?'Hotel':s.type==='Transport'?'Car':s.type==='Guide'?'Compass':'Leaf')}</span><span class="tag ${s.status==='Confirmed'?'green':'coral'}">${s.status}</span></div><div class="eyebrow">${esc(s.type)}</div><h3>${esc(s.name)}</h3><p>${esc(s.place)}</p><div class="row"><strong style="font-size:18px">${money(s.rate)}</strong><span class="notice">/ ${esc(s.unit)}</span></div><div class="notice" style="margin-top:9px">Rate valid until ${formatDate(s.expiry)} ${s.expiry.slice(0,4)}</div><div class="row"><span class="notice">${s.leadId?esc(lead(s.leadId)?.name):'Unassigned'}</span><button class="btn ghost" data-supplier="${s.id}">View partner ${i('ArrowRight')}</button></div></article>`).join('')}</div>`}
const ruleDefs=[['Reply deadline reminders','Keep a next action on new enquiries so no traveller falls through the cracks.'],['Proposal follow-up reminders','Queue an internal reminder when a proposal needs a personal follow-up.'],['Booking preparation tasks','Add deposit, supplier and departure checks when a booking is confirmed.'],['Payment due reminders','Show the team upcoming balance dates. Never chase a traveller without review.']];
function automations(){const queue=state.leads.filter(l=>l.stage===2&&!state.approved.includes(l.id));return heading('Thoughtful follow-ups. Always human.','Let the desk remember the details. Keep the conversation personal.','','AUTOMATION & APPROVALS')+`<div class="split-view"><section class="panel"><div class="panel-header"><h3>Internal workflow rules</h3><span class="tag">Local demo rules</span></div>${ruleDefs.map(([t,d],j)=>`<div class="rule"><div><h4>${t}</h4><p>${d}</p></div><button class="toggle ${state.rules[j]?'on':''}" data-rule="${j}" role="switch" aria-checked="${state.rules[j]}" aria-label="${t}"></button></div>`).join('')}<div class="padded"><p class="notice">Rules apply when you create an enquiry, save a proposal or confirm a booking in this demo. Scheduled delivery requires a connected backend.</p></div></section><div class="stack"><section class="panel padded"><div class="eyebrow">OUR HUMAN-FIRST PROMISE</div><h3 style="font-size:19px;line-height:1.5">A little automation.<br>A lot of personal care.</h3><p class="notice" style="margin-top:15px">Messages stay as drafts until a team member reviews them. Nothing is sent from this prototype.</p></section></div></div><section class="panel" style="margin-top:22px"><div class="panel-header"><h3>Ready for a human touch</h3><span class="tag coral">${queue.length} to review</span></div>${queue.map(l=>`<div class="rule"><div><h4>Proposal follow-up · ${esc(l.name)}</h4><p>Hi ${esc(l.name)}, have you had a chance to look through your ${esc(l.destination)} journey? Happy to adjust the pace, stays or experiences to make it feel right for you.</p></div><button class="btn light" data-review-message="${l.id}">Review draft ${i('ArrowRight')}</button></div>`).join('')||'<div class="empty">All caught up. Saved proposals will appear here for review.</div>'}</section>`}
function insights(){const total=state.leads.length,confirmed=booked().length;return heading('Know what moves your business forward.','An honest view of your enquiry-to-booking journey.','','WORKSPACE INSIGHTS')+pilotMeasures()+`<div class="metrics">${metric('Enquiries in workspace',total,'All sources · seeded and newly added','Users')}${metric('Booking conversion',Math.round(confirmed/total*100)+'%',`${confirmed} confirmed / ${total} enquiries`,'ChartNoAxesCombined')}${metric('Follow-ups completed',state.tasks.filter(t=>t.done).length+'/'+state.tasks.length,'Completed internal tasks','CheckCircle2')}${metric('Average booking value',money(confirmed?booked().reduce((s,l)=>s+l.value,0)/confirmed:0),'Across confirmed bookings','Wallet')}</div><div class="report-grid"><section class="panel padded"><div class="eyebrow">ENQUIRY SOURCES</div><h3 style="font-size:16px">Where the conversations begin</h3>${['Instagram','Website','Referral','LinkedIn','WhatsApp'].map(s=>{let n=state.leads.filter(l=>l.source===s).length;return `<div class="bar-row"><span>${s}</span><div class="bar-track"><span style="width:${n/total*100}%"></span></div><strong>${n}</strong></div>`}).join('')}</section><section class="panel padded"><div class="eyebrow">THE BOOKING FUNNEL</div><h3 style="font-size:16px">From first hello to confirmed</h3>${['All enquiries','Conversation or later','Proposal or later','Confirmed'].map((s,j)=>{let n=state.leads.filter(l=>l.stage>=j).length;return `<div class="bar-row" style="grid-template-columns:110px 1fr 25px"><span>${s}</span><div class="bar-track"><span style="width:${n/total*100}%"></span></div><strong>${n}</strong></div>`}).join('')}<p class="notice">Counts reflect current pipeline stages, not historical stage events.</p></section></div><div class="info-banner">${i('ChartNoAxesCombined')}Illustrative workspace metrics, not actual business results. Response time and quote preparation time would be measured after a real pilot establishes a baseline.</div>`}
function settings(){return heading('Your desk, your way.','A clear boundary between a pitch and production.','','WORKSPACE SETTINGS')+`<section class="panel padded"><h3>Presentation workspace</h3><p class="section-intro" style="margin-top:15px">All people, rates, payments and performance figures are sample data. Changes are saved locally in this browser. Email, WhatsApp, payments and AI services are not connected.</p><div class="actions-row">${button('Download workspace data','export-data','Download')}${button('Reset demo workspace','reset-confirm','RotateCcw','danger')}</div><div class="info-banner">${i('ShieldCheck')}For production: team authentication, a shared database, role permissions, approved messaging integrations, audit logs and real payment reconciliation.</div></section>`}
const pages={'Overview':overview,'Enquiries':enquiries,'Itinerary studio':studio,'Template library':library,'Bookings':bookings,'Payments':payments,'Suppliers':suppliers,'Automations':automations,'Insights':insights,'Settings':settings};
function render(){cleanupScene?.();cleanupScene=null;$('#app').innerHTML=shell();createIcons({icons:iconMap});if(page==='Overview')cleanupScene=mountLandscape($('#landscape'));bind();}
function go(p){page=p;search='';closeDrawer();render();window.scrollTo({top:0,behavior:'smooth'});}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
let previousFocus;
function drawer(title,body){previousFocus=document.activeElement;$('#overlay').innerHTML=`<div class="drawer-scrim"><section class="drawer" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header class="drawer-header"><h2>${title}</h2><button class="icon-btn" data-action="close" aria-label="Close panel">${i('X')}</button></header><div class="drawer-content">${body}</div></section></div>`;createIcons({icons:iconMap});bindOverlay();$('#overlay .drawer-header button').focus();}
function closeDrawer(){$('#overlay').innerHTML='';previousFocus?.focus?.();}
function field(label,name,value='',type='text',extra=''){return `<div class="field"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`}
function selectField(label,name,options,value){return `<div class="field"><label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${options.map(o=>`<option ${o===value?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`}
function newEnquiry(){drawer('Log an enquiry for the team',`<p class="notice" style="margin-bottom:18px">Staff entry for a phone call, referral or conversation received outside the inbox.</p><form id="enquiry-form"><div class="eyebrow">TRAVELLER BRIEF</div><div class="form-grid">${field('Traveller / organisation','name','','text','required maxlength="80"')}${field('Email address','email','','email','required')}${field('Phone / WhatsApp','phone','','tel')}${selectField('Enquiry source','source',['Website','Instagram','WhatsApp','LinkedIn','Referral'],'Website')}${selectField('Trip type','segment',['Leisure','Group','Corporate','Educational'],'Leisure')}${selectField('Destination interest','destination',['Meghalaya','Assam','Nagaland','Arunachal Pradesh','Sikkim','Manipur','Mizoram','Tripura'],'Meghalaya')}${field('Preferred travel date','date','2026-11-12','date','required min="2026-10-05"')}${field('Trip duration (days)','days',7,'number','required min="1" max="90"')}${field('Number of travellers','guests',4,'number','required min="1" max="500"')}${field('Total budget (₹)','budget',160000,'number','required min="1000" max="100000000"')}${selectField('Preferred contact','contact',['WhatsApp','Email','Phone'],'WhatsApp')}${selectField('Assigned to','owner',['Bonjeet','Ananya'],'Bonjeet')}${field('Next reply / action date','due',today,'date','required min="2026-10-05"')}<div class="field"><label for="f-flexible">Date flexibility</label><select id="f-flexible" name="flexible"><option value="true">Flexible by a few days</option><option value="false">Fixed dates</option></select></div><div class="field full" id="org-fields" hidden><label for="f-institution">Company / institution</label><input name="institution" id="f-institution" placeholder="Organisation name"><label for="f-objectives">Trip objectives</label><textarea name="objectives" id="f-objectives" placeholder="Learning outcomes, offsite goals or group needs"></textarea></div><div class="field full"><label for="f-preferences">Interests, pace & assistance needs</label><textarea id="f-preferences" name="preferences" placeholder="Nature, local food, slower pace, dietary preferences…"></textarea></div></div><button class="btn primary" type="submit">${i('Plus')}Add to enquiry desk</button></form>`);$('#f-segment').onchange=e=>{$('#org-fields').hidden=!['Corporate','Educational'].includes(e.target.value)};$('#enquiry-form').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));let l={...d,id:Date.now(),guests:+d.guests,days:+d.days,budget:+d.budget,value:+d.budget,flexible:d.flexible==='true',stage:0,trip:d.destination+' custom journey',events:['Enquiry logged manually by a team member']};state.leads.unshift(l);if(state.rules[0])state.tasks.unshift({id:Date.now(),title:'Reply to '+l.name,sub:l.destination+' · New enquiry',leadId:l.id,due:l.due,done:false});save();closeDrawer();page='Enquiries';render();toast('Enquiry added. Your next action is ready.');};}
function openLead(id){const l=lead(id);drawer('Traveller workspace',`<div class="lead-person">${avatar(l.name)}<div><h3>${esc(l.name)}</h3><p>${esc(l.email)} · ${esc(l.source)}</p></div></div>${status(l)}<div class="detail-grid"><div><label>Journey</label><strong>${esc(l.destination)} · ${l.days} days</strong></div><div><label>Travel dates</label><strong>${formatDate(l.date)} ${l.date.slice(0,4)}${l.flexible?' · Flexible':''}</strong></div><div><label>Travellers</label><strong>${l.guests} · ${esc(l.segment)}</strong></div><div><label>Total budget</label><strong>${money(l.budget)}</strong></div><div><label>Preferred contact</label><strong>${esc(l.contact||'Email')}${l.phone?' · '+esc(l.phone):''}</strong></div><div><label>Proposed value</label><strong>${money(l.value)}</strong></div></div><div class="detail-section"><h3>What matters to them</h3><button class="btn ghost" data-assistant="${l.id}">${i('Sparkles')}Planning assistant</button><p>${esc(l.preferences||'No preferences captured yet.')}</p>${l.institution?`<p style="margin-top:10px"><strong>${esc(l.institution)}</strong><br>${esc(l.objectives)}</p>`:''}</div><form id="lead-update" class="detail-section"><div class="form-grid">${selectField('Responsible teammate','owner',['Bonjeet','Ananya'],l.owner)}${field('Next action date','due',l.due,'date','required')}${selectField('Pipeline stage','stage',stages,stages[l.stage])}</div><button class="btn light" type="submit">${i('Check')}Save next action</button></form><div class="actions-row"><button class="btn primary" data-studio="${l.id}">${i('Map')}Build proposal</button>${l.stage===3?`<button class="btn light" data-booking="${l.id}">${i('Compass')}Open booking</button>`:l.stage===2?`<button class="btn lime" data-confirm="${l.id}">${i('Check')}Confirm booking</button>`:''}</div><div class="detail-section"><h3>Journey timeline</h3><div class="timeline">${l.events.map(ev=>`<div class="timeline-entry">${esc(ev)}<small>Demo workspace activity</small></div>`).join('')}</div></div>`);$('#lead-update').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));if(stages.indexOf(d.stage)===3&&l.stage!==3){l.owner=d.owner;l.due=d.due;confirmBooking(l.id);return}l.owner=d.owner;l.due=d.due;l.stage=stages.indexOf(d.stage);l.events.unshift('Owner, stage and next action updated');save();render();openLead(l.id);toast('Traveller workspace updated');};}
const checkLabels=['Traveller details verified','Deposit received','Stay & supplier confirmations','Route and accessibility reviewed','Emergency contacts shared','Final traveller briefing'];
function openAssistant(id){const l=lead(id);drawer('A thoughtful planning head start',`<div class="eyebrow">PLANNING ASSISTANT · SAMPLE OUTPUT</div><div class="info-banner">${i('Sparkles')}This frontend demonstrates the review experience using a template. A live AI service is not connected.</div><h3 style="font-size:15px">Traveller brief, at a glance</h3><p class="section-intro" style="font-size:12px;margin-top:12px">${esc(l.name)} is exploring ${l.destination} for ${l.guests} travellers over ${l.days} days, starting ${formatDate(l.date)}. Group budget: ${money(l.budget)}.</p><div class="detail-section"><h3>Personalise the plan around</h3><p>${esc(l.preferences||'Ask about interests, pace, food and assistance needs.')}</p></div><div class="detail-section"><h3>A first reply to make your own</h3><div class="field"><label for="assistant-reply">Editable suggested reply</label><textarea id="assistant-reply" style="min-height:155px">Hello ${esc(l.name)}, thank you for thinking of The Rainbow Butterflies for your ${esc(l.destination)} journey. I’d love to shape these ${l.days} days around your group. Could we have a quick conversation about your preferred pace, stays and any dietary or assistance needs?</textarea></div><button class="btn primary" id="save-assistant">${i('Check')}Approve and save draft</button><p class="notice" style="margin-top:12px">Saving records your approval. It does not send a message.</p></div>`);$('#save-assistant').onclick=()=>{l.approvedMessage=$('#assistant-reply').value;l.events.unshift('Personal reply draft approved (not sent)');save();openLead(id);toast('Approved draft saved to traveller record')};}
function openBooking(id){let l=lead(id);state.checks[l.id]??=[false,false,false,false,false,false];let checks=state.checks[l.id];drawer('Departure workspace',`<div class="eyebrow">${esc(l.destination)} · ${formatDate(l.date)}</div><h3 style="font-size:23px;letter-spacing:-.8px">${esc(l.trip)}</h3><p class="notice" style="margin-top:8px">${esc(l.name)} · ${l.guests} travellers · Owner: ${esc(l.owner)}</p><div class="detail-grid"><div><label>Booking value</label><strong>${money(l.value)}</strong></div><div><label>Balance remaining</label><strong>${money(Math.max(0,l.value-receipts(l.id)))}</strong></div></div><div class="detail-section"><h3>Ready, set, explore.</h3>${checkLabels.map((t,j)=>`<div class="task-row ${checks[j]?'completed':''}" style="padding-inline:0"><button class="check ${checks[j]?'done':''}" data-check="${j}" data-trip="${l.id}" aria-label="Toggle ${t}" aria-pressed="${checks[j]}">${checks[j]?i('Check'):''}</button><div><strong>${t}</strong></div></div>`).join('')}</div><div class="detail-section"><h3>Partner confirmations</h3>${state.suppliers.filter(s=>s.leadId===l.id).map(s=>`<div class="template-item"><div><strong>${esc(s.name)}</strong><small>${esc(s.type)}</small></div><span class="tag ${s.status==='Confirmed'?'green':'coral'}">${s.status}</span></div>`).join('')||'<p>Assign partners from the supplier directory.</p>'}</div><div class="actions-row"><button class="btn primary" data-pay="${l.id}">${i('Wallet')}Record payment</button><button class="btn light" data-lead="${l.id}">${i('Users')}Traveller details</button></div>`)}
function confirmBooking(id){const l=lead(id);l.stage=3;l.events.unshift('Proposal accepted; booking confirmed');state.checks[id]??=[true,false,false,false,false,false];if(state.rules[2])state.tasks.unshift({id:Date.now(),leadId:id,title:'Prepare '+l.name+'’s departure',sub:l.destination+' · Confirm suppliers & deposit',due:l.due,done:false});if(state.rules[3])state.tasks.unshift({id:Date.now()+1,leadId:id,title:'Review balance for '+l.name,sub:'Internal payment reminder',due:l.due,done:false});save();closeDrawer();page='Bookings';render();openBooking(id);toast('Booking confirmed. Trip preparation is ready.');}
function paymentForm(id){drawer('Record a payment',`<p class="notice" style="margin-bottom:18px">Record an offline transaction for this demo. No money is charged or transferred.</p><form id="payment-form"><div class="field"><label for="p-booking">Booking</label><select id="p-booking" name="leadId">${booked().map(l=>`<option value="${l.id}" ${Number(id)===l.id?'selected':''}>${esc(l.name)} · ${esc(l.destination)}</option>`).join('')}</select></div>${selectField('Entry type','type',['Traveller receipt','Supplier payment'],'Traveller receipt')}${field('Amount (₹)','amount','','number','required min="1" max="100000000" step="1"')}${field('Transaction date','date',today,'date','required')}${field('Reference / note','ref','','text','required maxlength="100"')}<button class="btn primary" type="submit">${i('Check')}Save ledger entry</button></form>`);$('#payment-form').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));const l=lead(d.leadId);if(d.type==='Traveller receipt'&&+d.amount>l.value-receipts(l.id)){toast('Amount exceeds the outstanding traveller balance.');return}state.payments.push({...d,id:Date.now(),leadId:+d.leadId,amount:+d.amount});l.events.unshift(d.type+' recorded: '+money(+d.amount));save();closeDrawer();render();toast('Payment recorded in the demo ledger');};}
function supplierForm(id){let s=state.suppliers.find(s=>s.id===Number(id));drawer(s?'Partner details':'Add a local partner',`<form id="supplier-form">${field('Partner name','name',s?.name||'','text','required')}${selectField('Partner type','type',['Stay','Guide','Transport','Activity'],s?.type||'Stay')}${field('Location','place',s?.place||'','text','required')}${field('Contact details','contact',s?.contact||'','text','required')}<div class="form-grid">${field('Indicative rate (₹)','rate',s?.rate||'','number','required min="1"')}${field('Rate unit','unit',s?.unit||'day','text','required')}${field('Rate expiry','expiry',s?.expiry||'2026-12-31','date','required')}${selectField('Confirmation status','status',['Pending','Confirmed'],s?.status||'Pending')}</div><div class="field"><label for="s-booking">Assigned booking</label><select id="s-booking" name="leadId"><option value="">Unassigned</option>${booked().map(l=>`<option value="${l.id}" ${s?.leadId===l.id?'selected':''}>${esc(l.name)}</option>`).join('')}</select></div><button class="btn primary" type="submit">${i('Check')}Save partner</button></form>`);$('#supplier-form').onsubmit=e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));let updated={...d,id:s?.id||Date.now(),rate:+d.rate,leadId:d.leadId?+d.leadId:null};if(s)Object.assign(s,updated);else state.suppliers.push(updated);save();closeDrawer();render();toast('Partner details saved');};}
function customDay(){drawer('Write a day worth remembering',`<form id="day-form">${field('Day title','title','','text','required')}${field('Location / route','place','','text','required')}${field('Experience tags','type','Culture · Slow travel')}<div class="field"><label for="day-detail">Description</label><textarea id="day-detail" name="detail" required></textarea></div><button class="btn primary" type="submit">${i('Plus')}Add to itinerary</button></form>`);$('#day-form').onsubmit=e=>{e.preventDefault();getProposal().days.push(Object.fromEntries(new FormData(e.target)));save();closeDrawer();render();toast('Custom day added');};}
function proposalPreview(){const l=lead(selectedLead),p=getProposal(),c=calc(p);drawer('Your journey, beautifully considered',`<div class="eyebrow">THE RAINBOW BUTTERFLIES · PROPOSAL</div><h3 style="font-size:24px;line-height:1.4">${esc(l.trip)}</h3><p class="notice" style="margin-top:12px">Prepared for ${esc(l.name)} · ${l.guests} travellers<br>${formatDate(l.date)} · ${p.days.length} days</p><div class="quote-total">${money(c.total)}</div><p class="notice">${money(c.total/l.guests)} per person · Indicative group quote</p>${p.days.map((d,j)=>`<div class="detail-section"><div class="eyebrow">DAY ${j+1} · ${esc(d.place)}</div><h3>${esc(d.title)}</h3><p>${esc(d.detail)}</p></div>`).join('')}<div class="info-banner">${i('ShieldCheck')}Demo proposal. Availability, route suitability, final inclusions, taxes and terms must be approved by the operator before sharing.</div><div class="actions-row">${button('Download proposal','download-proposal','Download')}${button('Print / save PDF','print-proposal','Printer')}</div>`)}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));let a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function downloadProposal(){const l=lead(selectedLead),p=getProposal(),c=calc(p);download('Rainbow-Butterflies-Proposal-'+l.name.replace(/[^a-z0-9]/gi,'-')+'.html',`<!doctype html><html><head><meta charset="utf-8"><title>Journey proposal</title><style>body{font-family:Georgia,serif;max-width:740px;margin:70px auto;padding:25px;color:#284438;line-height:1.8}h1{font-size:36px}h2{margin-top:35px}small{color:#819375}.price{font-size:28px;border-block:1px solid #ddd;padding:20px}footer{margin-top:50px;font-size:12px;color:#77836f}@media print{body{margin:20px}}</style></head><body><small>THE RAINBOW BUTTERFLIES · DEMO PROPOSAL</small><h1>${esc(l.trip)}</h1><p>Prepared for ${esc(l.name)} · ${l.guests} travellers<br>${formatDate(l.date)} ${l.date.slice(0,4)} · ${p.days.length} days</p><div class="price">${money(c.total)} <small>group price · ${money(c.total/l.guests)} per person</small></div>${p.days.map((d,j)=>`<h2>Day ${j+1} · ${esc(d.title)}</h2><small>${esc(d.place)}</small><p>${esc(d.detail)}</p>`).join('')}<footer>Illustrative demo proposal only. Confirm availability, route suitability, accessibility, inclusions, taxes and cancellation terms before issuing a real quote.</footer></body></html>`,'text/html');toast('Presentation proposal downloaded')}
const templates=[{title:'A Khasi kitchen afternoon',place:'Shillong',type:'Food · Community experience',detail:'Cook a seasonal meal with a local host and hear the stories behind the ingredients.'},{title:'Tea gardens, unhurried',place:'Jorhat, Assam',type:'Tea · Estate visit',detail:'Walk through tea gardens with a local guide and enjoy a tasting, subject to estate permission.'},{title:'A gentle day in the hills',place:'Shillong',type:'Accessible pace · Rest day',detail:'A slower day with short walks, scenic stops and plenty of time to rest. Confirm individual access needs.'}];
const actions={
'review-inbox':()=>go('Enquiries'),'simulate-incoming':simulateIncoming,'new-enquiry':newEnquiry,close:closeDrawer,studio:()=>{selectedLead=1;go('Itinerary studio')},notifications:()=>drawer('Your next little steps',`<p class="notice" style="margin-bottom:15px">Internal reminders. The traveller gets a personal reply from your team.</p>${state.tasks.map(taskRow).join('')}`),'record-payment':()=>paymentForm(), 'new-supplier':()=>supplierForm(),'custom-day':customDay,'preview-proposal':proposalPreview,'download-proposal':downloadProposal,'print-proposal':()=>{closeDrawer();window.print()},
'save-proposal':()=>{let l=lead(selectedLead),p=getProposal(),c=calc(p);if(!p.days.length){toast('Add at least one day before saving a proposal.');return}p.versions.push({n:p.versions.length+1,date:new Date().toLocaleDateString('en-IN',{day:'numeric',month:'short'}),total:c.total,days:JSON.parse(JSON.stringify(p.days)),costs:{...p.costs},margin:p.margin});l.value=c.total;l.days=p.days.length;if(l.stage<3)l.stage=2;l.events.unshift('Proposal v'+p.versions.length+' saved for human review');state.approved=state.approved.filter(id=>id!==l.id);if(state.rules[1]&&!state.tasks.some(t=>t.leadId===l.id&&!t.done&&t.title.startsWith('Follow up')))state.tasks.unshift({id:Date.now(),leadId:l.id,title:'Follow up with '+l.name,sub:'Proposal v'+p.versions.length+' · '+l.destination,due:l.due,done:false});save();render();toast('Proposal version saved. Follow-up queued; nothing sent.');},
'export-data':()=>download('butterfly-desk-workspace.json',JSON.stringify(state,null,2),'application/json'),
'export-payments':()=>{let rows=[['Reference','Traveller','Type','Date','Amount INR'],...state.payments.map(p=>[p.ref,lead(p.leadId)?.name,p.type,p.date,p.amount])];download('butterfly-desk-ledger.csv',rows.map(r=>r.map(c=>'"'+String(c??'').replace(/^[=+@-]/,"'").replaceAll('"','""')+'"').join(',')).join('\n'),'text/csv');toast('Ledger exported')},
'reset-confirm':()=>drawer('Reset the presentation?',`<p class="section-intro">This restores the original sample enquiries, itineraries and payments. Any changes in this demo browser will be removed. You can download the workspace first.</p><div class="actions-row">${button('Download backup','export-data','Download')}${button('Restore sample data','reset','RotateCcw','danger')}</div>`),
reset:()=>{state=seed();selectedLead=1;save();go('Overview');toast('Original demo restored')}
};
function bindCommon(root){bindExtensions(root);root.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>go(el.dataset.page));root.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>actions[el.dataset.action]?.());root.querySelectorAll('[data-lead]').forEach(el=>{el.onclick=()=>openLead(el.dataset.lead);el.onkeydown=e=>{if(e.key==='Enter')openLead(el.dataset.lead)}});root.querySelectorAll('[data-booking]').forEach(el=>{el.onclick=()=>openBooking(el.dataset.booking);el.onkeydown=e=>{if(e.key==='Enter')openBooking(el.dataset.booking)}});root.querySelectorAll('[data-task]').forEach(el=>el.onclick=()=>{const t=state.tasks.find(t=>t.id===+el.dataset.task);t.done=!t.done;save();const inDrawer=!!$('#overlay .drawer');render();if(inDrawer)actions.notifications();toast(t.done?'Task complete. One less thing to remember.':'Task reopened');});root.querySelectorAll('[data-assistant]').forEach(el=>el.onclick=()=>openAssistant(+el.dataset.assistant));root.querySelectorAll('[data-studio]').forEach(el=>el.onclick=()=>{selectedLead=+el.dataset.studio;go('Itinerary studio')});root.querySelectorAll('[data-confirm]').forEach(el=>el.onclick=()=>confirmBooking(+el.dataset.confirm));root.querySelectorAll('[data-pay]').forEach(el=>el.onclick=()=>paymentForm(+el.dataset.pay));root.querySelectorAll('[data-supplier]').forEach(el=>el.onclick=()=>supplierForm(+el.dataset.supplier));}
function bindOverlay(){bindCommon($('#overlay'));$('.drawer-scrim').onclick=e=>{if(e.target.classList.contains('drawer-scrim'))closeDrawer()};$$('[data-check]').forEach(el=>el.onclick=()=>{let id=+el.dataset.trip,j=+el.dataset.check;state.checks[id][j]=!state.checks[id][j];save();render();openBooking(id)});}
function bind(){bindCommon($('#app'));$('#global-search')?.addEventListener('input',e=>{let pos=e.target.selectionStart;search=e.target.value;render();$('#global-search').focus();$('#global-search').setSelectionRange(pos,pos)});$$('[data-view]').forEach(el=>el.onclick=()=>{pipelineView=el.dataset.view;render()});$('#source-filter')?.addEventListener('change',e=>{sourceFilter=e.target.value;render()});$('#studio-traveller')?.addEventListener('change',e=>{selectedLead=+e.target.value;render()});$$('[data-cost]').forEach(el=>el.onchange=()=>{el.value=Math.max(0,Math.min(10000000,Number(el.value)||0));getProposal().costs[el.dataset.cost]=+el.value;save();refreshPrice()});$('#markup')?.addEventListener('change',e=>{e.target.value=Math.max(0,Math.min(200,Number(e.target.value)||0));getProposal().margin=+e.target.value;save();refreshPrice()});$$('[data-day-up],[data-day-down],[data-day-remove]').forEach(el=>el.onclick=()=>{let p=getProposal();if(el.dataset.dayRemove!==undefined)p.days.splice(+el.dataset.dayRemove,1);else{let j=Number(el.dataset.dayUp??el.dataset.dayDown),k=j+(el.dataset.dayUp!==undefined?-1:1);[p.days[j],p.days[k]]=[p.days[k],p.days[j]]}save();render()});$$('[data-template]').forEach(el=>el.onclick=()=>{getProposal().days.push({...templates[+el.dataset.template]});save();render();toast('Experience added to your itinerary')});$$('[data-rule]').forEach(el=>el.onclick=()=>{let j=+el.dataset.rule;state.rules[j]=!state.rules[j];save();render();toast('Workflow rule '+(state.rules[j]?'enabled':'paused'))});$$('[data-review-message]').forEach(el=>el.onclick=()=>{let l=lead(el.dataset.reviewMessage);drawer('Review your personal follow-up',`<div class="eyebrow">${esc(l.name)} · ${esc(l.destination)}</div><div class="field"><label for="message-draft">Your message</label><textarea id="message-draft" style="min-height:160px">Hi ${esc(l.name)}, have you had a chance to look through your ${esc(l.destination)} journey? Happy to adjust the pace, stays or experiences to make it feel right for you.</textarea></div><div class="info-banner">${i('ShieldCheck')}Approval saves this message locally. No email or WhatsApp message will be sent.</div><button class="btn primary" id="approve-message">${i('Check')}Approve draft</button>`);$('#approve-message').onclick=()=>{l.approvedMessage=$('#message-draft').value;state.approved.push(l.id);l.events.unshift('Follow-up draft approved (not sent)');save();closeDrawer();render();toast('Draft approved and saved. No message was sent.')}});}
function refreshPrice(){let c=calc(getProposal());$('#cost-total').textContent=money(c.cost);$('#quote-total').textContent=money(c.total);$('#per-person').textContent=money(c.total/lead(selectedLead).guests)+' per traveller · '+lead(selectedLead).guests+' travellers';}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawer();if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();$('#global-search')?.focus()}if(e.key==='Tab'&&$('#overlay .drawer')){let els=[...$('#overlay').querySelectorAll('button,input,select,textarea,a[href]')].filter(el=>!el.disabled&&el.offsetParent!==null);const first=els[0],last=els.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
function inboxStrip(){return `<section class="panel padded" style="margin-bottom:20px"><div class="toolbar" style="margin:0"><div><div class="eyebrow">CHANNEL INBOX · DEMONSTRATION</div><p class="notice">Website · WhatsApp · Instagram · Email · Referrals</p><p class="notice">Incoming leads appear here for your team to review. Sample connections only.</p></div>${button('Simulate incoming lead','simulate-incoming','Plus')}</div></section>`}
function simulateIncoming(){state.demoIncoming=(state.demoIncoming||0)+1;let n=state.demoIncoming;let l={id:Date.now(),name:'Incoming traveller '+n,email:'traveller'+n+'@example.com',phone:'',destination:'Meghalaya',trip:'Meghalaya custom journey',date:'2026-11-20',days:7,guests:4,budget:160000,value:160000,source:n%2?'WhatsApp':'Website',stage:0,owner:'Bonjeet',due:today,segment:'Leisure',preferences:'Interested in local food, nature and a relaxed pace.',contact:'WhatsApp',flexible:true,events:['Sample enquiry received through the channel inbox']};state.leads.unshift(l);state.tasks.unshift({id:Date.now()+1,title:'Review incoming enquiry from '+l.name,sub:l.source+' · Assign and qualify',leadId:l.id,due:today,done:false});save();render();openLead(l.id);toast('Sample incoming enquiry added to the team inbox');}
function libraryItems(){return state.library??=( [{id:1,type:'Route',name:'Meghalaya slow-travel route',location:'Meghalaya',description:'Seven days through Shillong, Sohra, Nongriat and the Umngot River.',approved:true},{id:2,type:'Stay',name:'Khasi Hills homestay package',location:'Meghalaya',description:'₹3,200 per room per night. Demo package: 2 rooms × 6 nights.',approved:true},{id:3,type:'Activity',name:'A Khasi kitchen afternoon',location:'Shillong',description:'A community-hosted cooking experience. ₹1,200 per traveller.',approved:true},{id:4,type:'Quote template',name:'Private leisure journey',location:'All destinations',description:'25% markup on operating costs. Personalised, day-by-day proposal.',approved:true},{id:5,type:'Quote template',name:'Corporate retreat proposal',location:'All destinations',description:'20% markup. Organiser brief and group objectives accompany the proposal.',approved:false},{id:6,type:'Route',name:'Assam tea and culture trail',location:'Assam',description:'Five days of tea gardens, local culture and unhurried stays.',approved:false}]);}
function library(){return heading('Your team’s planning library','Reusable routes, stays, activities and quote templates. Review once, reuse thoughtfully.','','APPROVED COMPONENTS')+`<div class="info-banner">${i('ShieldCheck')}Approval statuses and supplier rates are illustrative for this pitch. Components marked draft must be approved before use.</div><div class="cards-grid">${libraryItems().map(t=>`<article class="panel card-body"><div class="row" style="margin-top:0"><span class="eyebrow">${t.type}</span><span class="tag ${t.approved?'green':'coral'}">${t.approved?'Approved':'Needs review'}</span></div><h3>${t.name}</h3><p>${t.description}</p><div class="notice" style="margin-top:12px">${t.location} · ${t.approved?'Reviewed by Bonjeet':'Draft by Ananya'}</div><div class="actions-row"><button class="btn ${t.approved?'primary':'light'}" data-library="${t.id}">${i(t.approved?'Plus':'ShieldCheck')}${t.approved?'Use in proposal':'Review component'}</button></div></article>`).join('')}</div>`;}
function openLibrary(id){const t=libraryItems().find(t=>t.id===id);drawer(t.approved?'Use approved component':'Review library component',`<div class="eyebrow">${t.type} · ${t.location}</div><h3>${t.name}</h3><p class="section-intro" style="margin-top:15px">${t.description}</p>${t.approved?`<div class="field" style="margin-top:20px"><label for="library-lead">Apply to traveller proposal</label><select id="library-lead">${state.leads.map(l=>`<option value="${l.id}" ${l.id===selectedLead?'selected':''}>${esc(l.name)} · ${esc(l.destination)}</option>`).join('')}</select></div><div class="info-banner">${i('FileText')}${t.type==='Route'?'Replaces the working itinerary days. Saved proposal versions remain in history.':t.type==='Stay'?'Sets the stays cost to ₹38,400.':t.type==='Activity'?'Adds an itinerary day and ₹1,200 per traveller to experiences.':'Sets the proposal markup to '+(t.id===5?'20':'25')+'%.'}</div><button class="btn primary" id="apply-library">Apply to working draft</button>`:`<div class="info-banner">${i('ShieldCheck')}Demo review: confirm the route, rate or pricing policy before making this available to the team.</div><button class="btn primary" id="approve-library">Approve for team use</button>`}`);if(!t.approved){$('#approve-library').onclick=()=>{t.approved=true;save();closeDrawer();render();toast('Component approved for the demo library')};return}$('#apply-library').onclick=()=>{selectedLead=+$('#library-lead').value;const l=lead(selectedLead),p=getProposal();if(t.type==='Route'&&l.destination!==t.location){toast('Choose a traveller whose destination matches this route.');return}if(t.type==='Route')p.days=initialRoute({...l,days:t.id===1?7:5});if(t.type==='Stay')p.costs.stays=38400;if(t.type==='Activity'){p.days.push({...templates[0]});p.costs.experiences+=1200*l.guests}if(t.type==='Quote template')p.margin=t.id===5?20:25;l.events.unshift('Approved library component applied: '+t.name);save();go('Itinerary studio');toast('Approved component applied to working proposal')};}
function paymentOperations(){state.reminders??={};return `<div class="report-grid" style="margin-bottom:22px"><section class="panel"><div class="panel-header"><div><h3>Payment reminder desk</h3><p class="sub">Internal review queue · demo dates</p></div><span class="tag coral">${booked().filter(l=>l.value>receipts(l.id)).length} balances</span></div>${booked().filter(l=>l.value>receipts(l.id)).map(l=>`<div class="rule"><div><h4>${esc(l.name)} · ${money(l.value-receipts(l.id))}</h4><p>Due ${formatDate(l.due)} · ${state.reminders[l.id]?'Draft approved, not sent':'Awaiting team review'}</p></div><button class="btn light" data-reminder="${l.id}">${state.reminders[l.id]?'View draft':'Review reminder'}</button></div>`).join('')||'<div class="empty">No outstanding balances.</div>'}</section><section class="panel"><div class="panel-header"><div><h3>Payment reconciliation</h3><p class="sub">Match a sample bank entry to the ledger</p></div></div>${state.payments.filter(p=>p.type==='Traveller receipt').slice(0,3).map(p=>`<div class="rule"><div><h4>${money(p.amount)} · ${esc(lead(p.leadId)?.name)}</h4><p>Sample bank reference: BANK-${esc(p.ref)}<br>Ledger reference: ${esc(p.ref)}</p></div>${p.reconciled?'<span class="tag green">Reconciled</span>':`<button class="btn light" data-reconcile="${p.id}">Match entry</button>`}</div>`).join('')}<p class="notice padded">Sample bank entries mirror demo receipts. No bank account is connected.</p></section></div>`;}
function openReminder(id){let l=lead(id);drawer('Review balance reminder',`<div class="eyebrow">${esc(l.name)} · DUE ${formatDate(l.due)}</div><div class="field"><label for="balance-draft">Suggested message</label><textarea id="balance-draft" style="min-height:150px">${esc(state.reminders?.[id]||`Hello ${l.name}, a quick note about your ${l.destination} journey: the remaining balance is ${money(l.value-receipts(id))}, due ${formatDate(l.due)}. Please let us know if you need the payment details or have any questions.`)}</textarea></div><p class="notice">Approve this sample reminder for the team. No message is sent.</p><div class="actions-row"><button class="btn primary" id="approve-reminder">Approve reminder draft</button></div>`);$('#approve-reminder').onclick=()=>{state.reminders??={};state.reminders[id]=$('#balance-draft').value;save();closeDrawer();render();toast('Balance reminder approved in the demo')};}
function pilotMeasures(){return `<section class="panel padded" style="margin-bottom:22px"><div class="eyebrow">PILOT SCORECARD · ILLUSTRATIVE TARGETS</div><h3 style="font-size:15px;margin-bottom:18px">What the pilot would measure</h3><div class="metrics" style="margin-bottom:0">${metric('Clarification messages','6 → 2','Example before / after · not measured','Mail')}${metric('Quote preparation','90 → 25 min','Example before / after · not measured','Clock')}${metric('Missed confirmations','4 → 0','Example before / after · not measured','CheckCircle2')}${metric('Founder admin time','8 → 3 h','Example weekly target · not measured','Users')}</div></section>`;}
function bindExtensions(root){root.querySelectorAll('[data-library]').forEach(el=>el.onclick=()=>openLibrary(+el.dataset.library));root.querySelectorAll('[data-reminder]').forEach(el=>el.onclick=()=>openReminder(+el.dataset.reminder));root.querySelectorAll('[data-reconcile]').forEach(el=>el.onclick=()=>{let p=state.payments.find(p=>p.id===+el.dataset.reconcile);drawer('Match bank entry to ledger',`<h3>${esc(lead(p.leadId)?.name)} · ${money(p.amount)}</h3><div class="detail-grid"><div><label>Sample bank entry</label><strong>BANK-${esc(p.ref)}</strong></div><div><label>Ledger entry</label><strong>${esc(p.ref)}</strong></div><div><label>Bank amount</label><strong>${money(p.amount)}</strong></div><div><label>Ledger amount</label><strong>${money(p.amount)}</strong></div></div><p class="notice">Amounts match. Confirm this demonstration match to mark the ledger entry reconciled.</p><div class="actions-row"><button class="btn primary" id="confirm-match">Confirm match</button></div>`);$('#confirm-match').onclick=()=>{p.reconciled=true;save();closeDrawer();render();toast('Demo ledger entry reconciled')};});}

render();
